const meetingPlans={};let plannerDraft=null,plannerMonth=null;
const agendaTemplates=[['Project kickoff','Align on project goals, scope, stakeholders and delivery milestones.'],['Requirements discovery','Discuss user needs, workflows, constraints and acceptance criteria.'],['Technical review','Review architecture, integrations, security and open technical decisions.']];
const simpleMeetingSetup=meetingSetupDialog;
meetingSetupDialog=function(type){if(type==='recording')return simpleMeetingSetup(type);pendingMeetingSource=type;const saved=selected?requestDraft().sourceSettings?.[type]:null;const now=new Date(),date=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')+'-'+String(now.getDate()).padStart(2,'0');plannerDraft={title:saved?.title||'Product requirements discussion',date:saved?.date||date,time:saved?.time||'10:00',duration:saved?.duration||'60',agenda:saved?.agenda||'',language:saved?.language||'en-ja',link:saved?.link||(type==='zoom'?'https://zoom.us/j/12345678901':'https://meet.google.com/abc-defg-hij'),template:-1};plannerMonth=new Date(plannerDraft.date+'T12:00:00');drawMeetingPlanner();};
function setPlannerField(key,value){plannerDraft[key]=value;}
function shiftPlannerMonth(delta){plannerMonth=new Date(plannerMonth.getFullYear(),plannerMonth.getMonth()+delta,1);drawMeetingPlanner();}
function selectPlannerDay(date){plannerDraft.date=date;drawMeetingPlanner();}
function applyAgendaTemplate(i){plannerDraft.template=i;plannerDraft.agenda=agendaTemplates[i][1];drawMeetingPlanner();}
function loadMeetingPlan(i){plannerDraft={...meetingPlans[selected][i]};pendingMeetingSource=plannerDraft.provider;plannerMonth=new Date(plannerDraft.date+'T12:00:00');drawMeetingPlanner();}
function plannerCalendar(){const y=plannerMonth.getFullYear(),m=plannerMonth.getMonth(),days=new Date(y,m+1,0).getDate(),offset=new Date(y,m,1).getDay();return '<div class="planner-calendar-heading"><button type="button" aria-label="Previous month" onclick="shiftPlannerMonth(-1)">‹</button><strong>'+plannerMonth.toLocaleString(undefined,{month:'long',year:'numeric'})+'</strong><button type="button" aria-label="Next month" onclick="shiftPlannerMonth(1)">›</button></div><div class="planner-calendar">'+['S','M','T','W','T','F','S'].map(x=>'<small>'+x+'</small>').join('')+'<span></span>'.repeat(offset)+Array.from({length:days},(_,i)=>{const date=y+'-'+String(m+1).padStart(2,'0')+'-'+String(i+1).padStart(2,'0');return '<button type="button" aria-label="'+date+'" aria-pressed="'+(plannerDraft.date===date)+'" class="'+(plannerDraft.date===date?'selected':'')+'" onclick="selectPlannerDay(\''+date+'\')">'+(i+1)+'</button>';}).join('')+'</div>';}
function drawMeetingPlanner(){const box=document.getElementById('modal'),d=plannerDraft;box.className='meeting-planner-dialog';box.innerHTML='<div class="planner-top"><strong>Meeting planner</strong><button aria-label="Close meeting planner" onclick="document.getElementById(\'modal\').close()">×</button></div><div class="planner-layout"><aside class="planner-sidebar">'+plannerCalendar()+'<h3>Scheduled meetings</h3><p class="sub">'+esc(d.date)+' · This session</p><div class="planner-schedule">'+((meetingPlans[selected]||[]).map((p,i)=>({p,i})).filter(({p})=>p.date===d.date).map(({p,i})=>'<button type="button" onclick="loadMeetingPlan('+i+')"><small>'+esc(p.time)+' · '+esc(p.duration)+' min</small><strong>'+esc(p.title)+'</strong><span>'+meetingSourceLabels[p.provider]+'</span></button>').join('')||'<p class="planner-empty">No meetings scheduled for this day.</p>')+'</div></aside><form class="planner-main" onsubmit="saveMeetingPlan(event)"><span class="badge blue">'+meetingSourceLabels[pendingMeetingSource]+'</span><h2>Plan your next conversation</h2><label class="field">Meeting title<input name="title" required value="'+esc(d.title)+'" oninput="setPlannerField(\'title\',this.value)"></label><div class="planner-fields"><label class="field">Date<input type="date" required value="'+esc(d.date)+'" onchange="setPlannerField(\'date\',this.value)"></label><label class="field">Start time<input type="time" required value="'+esc(d.time)+'" onchange="setPlannerField(\'time\',this.value)"></label><label class="field">Duration<select onchange="setPlannerField(\'duration\',this.value)">'+['15','30','45','60','90','120'].map(x=>'<option value="'+x+'" '+(d.duration===x?'selected':'')+'>'+x+' min</option>').join('')+'</select></label></div><h3>Choose an agenda template</h3><div class="planner-templates">'+agendaTemplates.map(([title,desc],i)=>'<button type="button" aria-pressed="'+(d.template===i)+'" class="'+(d.template===i?'selected':'')+'" onclick="applyAgendaTemplate('+i+')"><span class="planner-template-top">'+icon('requirements')+'</span><strong>'+title+'</strong><small>'+desc+'</small></button>').join('')+'</div><label class="field">Agenda<textarea oninput="setPlannerField(\'agenda\',this.value)" placeholder="What would you like to discuss?">'+esc(d.agenda)+'</textarea></label><div class="planner-fields two"><label class="field">Demo meeting link<input value="'+esc(d.link)+'" oninput="setPlannerField(\'link\',this.value)"></label><label class="field">Translation<select onchange="setPlannerField(\'language\',this.value)"><option value="en-ja" '+(d.language==='en-ja'?'selected':'')+'>English → 日本語</option><option value="ja-en" '+(d.language==='ja-en'?'selected':'')+'>日本語 → English</option></select></label></div><p class="sub">Demo schedule only · No invitations or real meetings are created. Times use your local timezone.</p><div class="planner-footer"><button type="button" onclick="document.getElementById(\'modal\').className=\'recording-dialog\';meetingSourceDialog()">‹ Back</button><div><button type="submit" name="action" value="save">Save meeting</button><button class="primary" type="submit" name="action" value="start">Start preview →</button></div></div><p id="plannerError" role="alert"></p></form></div>';if(!box.open)box.showModal();}
function saveMeetingPlan(e){e.preventDefault();if(!selected){document.getElementById('plannerError').textContent='Select a project first.';return;}if(!plannerDraft.title.trim())return;const plan={...plannerDraft,provider:pendingMeetingSource};const list=meetingPlans[selected] ||= [];list.push(plan);const d=requestDraft();d.sourceSettings ||= {};d.sourceSettings[plan.provider]={...plan};if(e.submitter?.value==='start'){d.meetingType=plan.provider;d.title=plan.title;d.link=plan.link;d.tab='meeting';document.getElementById('modal').close();if(screen!=='request')navigate('request');startContextMeeting();}else{drawMeetingPlanner();toast('Meeting saved for this session.');}}
